package com.xplayer.lite;
import android.content.Context;
import android.net.Uri;
import androidx.test.core.app.ActivityScenario;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class ProTest {
 @Test public void favoritesAndSettingsPersist(){Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Uri u=Uri.parse("content://media/external/video/media/987654");if(ProPrefs.favorite(c,u))ProPrefs.toggle(c,u);assertTrue(ProPrefs.toggle(c,u));assertTrue(ProPrefs.favorite(c,u));assertFalse(ProPrefs.toggle(c,u));assertFalse(ProPrefs.favorite(c,u));ProPrefs.get(c).edit().putInt("seek",2).commit();assertEquals(2,ProPrefs.number(c,"seek",1));ProPrefs.get(c).edit().remove("seek").commit();}
 @Test public void settingsNavigation(){try(ActivityScenario<SettingsActivity> s=ActivityScenario.launch(SettingsActivity.class)){s.onActivity(a->{for(int i=0;i<13;i++){a.show(i);a.onBackPressed();}});}}
 @Test public void playerOverlayUsesFullScreen(){try(ActivityScenario<MainActivity> s=ActivityScenario.launch(MainActivity.class)){s.onActivity(a->{android.view.View root=a.findViewById(android.R.id.content);assertTrue(root instanceof android.widget.FrameLayout);assertTrue(root.getHeight()>0);assertTrue(hasDescription(root,"Player tools"));assertTrue(hasDescription(root,"Play or pause"));});}}
 @Test public void libraryNavigationVisible(){try(ActivityScenario<LibraryActivity> s=ActivityScenario.launch(LibraryActivity.class)){s.onActivity(a->{android.view.View root=a.findViewById(android.R.id.content);assertTrue(hasDescription(root,"Search"));assertTrue(hasDescription(root,"View and sort"));assertTrue(hasDescription(root,"Resume playback")||hasDescription(root,"استكمال المشاهدة"));});}}
 private boolean hasDescription(android.view.View v,String s){if(s.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return true;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(hasDescription(g.getChildAt(i),s))return true;}return false;}
 @Test public void captureNewScreens()throws Exception{try(ActivityScenario<LibraryActivity> s=ActivityScenario.launch(LibraryActivity.class)){capture("library.png");s.onActivity(a->{android.view.View v=find(a.findViewById(android.R.id.content),"View and sort");assertNotNull(v);v.performClick();});capture("view-sort.png");}try(ActivityScenario<SettingsActivity> s=ActivityScenario.launch(SettingsActivity.class)){capture("settings.png");s.onActivity(a->a.show(7));capture("about.png");}try(ActivityScenario<MainActivity> s=ActivityScenario.launch(MainActivity.class)){capture("player.png");s.onActivity(a->{android.view.View v=find(a.findViewById(android.R.id.content),"Player tools");assertNotNull(v);v.performClick();});capture("player-tools.png");}}
 private android.view.View find(android.view.View v,String s){if(v.getContentDescription()!=null&&s.contentEquals(v.getContentDescription()))return v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){android.view.View hit=find(g.getChildAt(i),s);if(hit!=null)return hit;}}return null;}
 private void capture(String name)throws Exception{InstrumentationRegistry.getInstrumentation().waitForIdleSync();android.graphics.Bitmap b=InstrumentationRegistry.getInstrumentation().getUiAutomation().takeScreenshot();assertNotNull(b);Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();java.io.File dir=new java.io.File(c.getFilesDir(),"ui-evidence");dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name))){assertTrue(b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out));}finally{b.recycle();}}
 @Test public void backgroundPolicyAndScanSettings(){Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();assertFalse(ProPrefs.backgroundAllowed(0,true));assertFalse(ProPrefs.backgroundAllowed(1,true));assertTrue(ProPrefs.backgroundAllowed(2,true));assertFalse(ProPrefs.backgroundAllowed(2,false));assertTrue(ProPrefs.backgroundAllowed(3,false));assertTrue(ProPrefs.hiddenPath(".hidden.mp4","Movies/"));assertTrue(ProPrefs.hiddenPath("clip.mp4","Movies/.private/"));assertFalse(ProPrefs.hiddenPath("clip.mp4","Movies/"));ProPrefs.save(c,"scan_extensions",java.util.Arrays.asList("mp4"));assertTrue(ProPrefs.allowedExtension(c,"clip.MP4"));assertFalse(ProPrefs.allowedExtension(c,"track.mp3"));ProPrefs.get(c).edit().remove("scan_extensions").commit();}
 @Test public void advancedSettingsBackup()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();ProPrefs.get(c).edit().putInt("background_mode",3).putInt("audio_delay",-500).putBoolean("gesture_osd",true).putInt("decoder_ext_mkv",2).commit();String json=Backup.exportJson(c);ProPrefs.get(c).edit().remove("background_mode").remove("audio_delay").remove("gesture_osd").remove("decoder_ext_mkv").commit();Backup.restore(c,json);assertEquals(3,ProPrefs.number(c,"background_mode",0));assertEquals(-500,ProPrefs.number(c,"audio_delay",0));assertTrue(ProPrefs.flag(c,"gesture_osd",false));assertEquals(2,ProPrefs.decoder(c,"clip.mkv",false));ProPrefs.get(c).edit().remove("background_mode").remove("audio_delay").remove("gesture_osd").remove("decoder_ext_mkv").commit();}
 @Test public void decoderLabelFitsAndToolbarScrolls(){try(ActivityScenario<MainActivity> s=ActivityScenario.launch(MainActivity.class)){s.onActivity(a->{android.view.View root=a.findViewById(android.R.id.content);android.view.View v=find(root,"Decoder");assertNotNull(v);assertTrue(v instanceof android.widget.TextView);android.widget.TextView text=(android.widget.TextView)v;assertEquals(1,text.getMaxLines());assertEquals("HW",text.getText().toString());android.view.View tool=find(root,"Audio track");assertNotNull(tool);assertTrue(tool.getParent().getParent() instanceof android.widget.HorizontalScrollView);});}}
 @Test public void volumeIndicatorAndOrientation()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();ProPrefs.get(c).edit().putBoolean("gesture_osd",true).commit();try(ActivityScenario<MainActivity> s=ActivityScenario.launch(MainActivity.class)){s.onActivity(a->{a.volumeOsdForTest();assertTrue(a.osdVisibleForTest());a.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);});Thread.sleep(1000);s.onActivity(a->{android.view.View root=a.findViewById(android.R.id.content);android.widget.TextView v=(android.widget.TextView)find(root,"Decoder");assertNotNull(v);assertTrue(v.getWidth()>0);assertTrue(v.getLayout()!=null&&v.getLayout().getLineCount()==1);android.view.View tool=find(root,"Audio track");assertNotNull(tool);assertTrue(tool.getMeasuredHeight()>0);});capture("player-landscape.png");}finally{ProPrefs.get(c).edit().remove("gesture_osd").commit();}}
 @Test public void loopPreferenceAndEngine()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();try(ActivityScenario<MainActivity> s=ActivityScenario.launch(MainActivity.class)){s.onActivity(a->{a.setRepeatForTest(1);assertEquals(1,ProPrefs.repeat(c));assertEquals(androidx.media3.common.Player.REPEAT_MODE_ONE,a.player.getRepeatMode());a.setRepeatForTest(2);assertEquals(2,a.repeatForTest());assertEquals(androidx.media3.common.Player.REPEAT_MODE_OFF,a.player.getRepeatMode());a.setRepeatForTest(0);assertEquals(0,ProPrefs.repeat(c));});}finally{ProPrefs.get(c).edit().remove("repeat_mode").commit();}}
 @Test public void activePlaybackNotificationAndMediaControls()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();java.io.File f=new java.io.File(c.getCacheDir(),"notification-test.mp3");try(java.io.InputStream in=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("sample.mp3");java.io.FileOutputStream out=new java.io.FileOutputStream(f)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}ProPrefs.get(c).edit().putBoolean("show_media_notification",true).commit();try(ActivityScenario<MainActivity> s=ActivityScenario.launch(new android.content.Intent(c,MainActivity.class).setAction(android.content.Intent.ACTION_VIEW).setData(Uri.fromFile(f)))){java.util.concurrent.atomic.AtomicReference<android.media.session.MediaSession.Token> token=new java.util.concurrent.atomic.AtomicReference<>();long deadline=android.os.SystemClock.elapsedRealtime()+15000;while(android.os.SystemClock.elapsedRealtime()<deadline){s.onActivity(a->{if(a.player.isPlaying()&&a.notificationActiveForTest())token.set(a.notificationTokenForTest());});if(token.get()!=null)break;Thread.sleep(100);}assertNotNull("Playing must create an active media session",token.get());android.app.NotificationManager nm=(android.app.NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);boolean found=false;for(android.service.notification.StatusBarNotification n:nm.getActiveNotifications())if(n.getId()==NowPlaying.ID){found=true;assertEquals("transport",n.getNotification().category);assertNotNull(n.getNotification().extras.getParcelable(android.app.Notification.EXTRA_MEDIA_SESSION));assertNotNull(n.getNotification().extras.getCharSequence(android.app.Notification.EXTRA_TITLE));}assertTrue("Media notification must actually be posted",found);android.media.session.MediaController ctrl=new android.media.session.MediaController(c,token.get());assertTrue((ctrl.getPlaybackState().getActions()&android.media.session.PlaybackState.ACTION_SEEK_TO)!=0);ctrl.getTransportControls().pause();Thread.sleep(400);s.onActivity(a->assertFalse(a.player.isPlaying()));ctrl.getTransportControls().seekTo(3000);Thread.sleep(400);s.onActivity(a->assertTrue(Math.abs(a.player.getCurrentPosition()-3000)<700));ctrl.getTransportControls().play();Thread.sleep(400);s.onActivity(a->assertTrue(a.player.getPlayWhenReady()));try(java.io.InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand("cmd statusbar expand-notifications"))){while(in.read()!=-1){}}Thread.sleep(500);try{capture("media-notification.png");}finally{try(android.os.ParcelFileDescriptor fd=InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand("cmd statusbar collapse")){}}}finally{ProPrefs.get(c).edit().remove("show_media_notification").commit();f.delete();}}
 @Test public void repeatAllActuallyWrapsQueue()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();java.io.File a=new java.io.File(c.getCacheDir(),"loop-a.mp3"),b=new java.io.File(c.getCacheDir(),"loop-b.mp3");for(java.io.File f:new java.io.File[]{a,b})try(java.io.InputStream in=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("sample.mp3");java.io.FileOutputStream out=new java.io.FileOutputStream(f)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}Uri first=Uri.fromFile(a),last=Uri.fromFile(b);ProPrefs.get(c).edit().putInt("repeat_mode",2).putBoolean("auto_next",false).commit();MainActivity.setLibraryQueue(java.util.Arrays.asList(first,last),last);try(ActivityScenario<MainActivity> s=ActivityScenario.launch(new android.content.Intent(c,MainActivity.class).setAction(android.content.Intent.ACTION_VIEW).setData(last).putExtra("library",true))){java.util.concurrent.atomic.AtomicBoolean ready=new java.util.concurrent.atomic.AtomicBoolean();long until=android.os.SystemClock.elapsedRealtime()+15000;while(android.os.SystemClock.elapsedRealtime()<until){s.onActivity(x->ready.set(x.player.isPlaying()&&x.player.getDuration()>0));if(ready.get())break;Thread.sleep(100);}assertTrue("last file playing",ready.get());s.onActivity(x->x.player.seekTo(Math.max(0,x.player.getDuration()-250)));java.util.concurrent.atomic.AtomicBoolean wrapped=new java.util.concurrent.atomic.AtomicBoolean();until=android.os.SystemClock.elapsedRealtime()+15000;while(android.os.SystemClock.elapsedRealtime()<until){s.onActivity(x->{androidx.media3.common.MediaItem item=x.player.getCurrentMediaItem();wrapped.set(item!=null&&item.localConfiguration!=null&&first.equals(item.localConfiguration.uri)&&x.player.isPlaying());});if(wrapped.get())break;Thread.sleep(100);}assertTrue("repeat all must wrap to first and continue",wrapped.get());}finally{ProPrefs.get(c).edit().remove("repeat_mode").remove("auto_next").commit();MainActivity.setLibraryQueue(java.util.Collections.emptyList(),last);a.delete();b.delete();}}
}
